119: // Case 5: Journal reopened on same path preserves state.
120: #[test]
121: fn journal_reopen_preserves_sequence() -> TestResult {
122:     use crate::FjallJournal;
123:     let fixture = PackedFixture::new()?;
124:     let (dir, journal) = open_test_journal()?;
125:     let artifact = fixture.submit(&journal, RuntimePolicy::Strict)?;
126:     assert_eq!(artifact.accepted_at_seq.get(), 1);
127:     fixture.check(&journal, &artifact, RuntimePolicy::Strict)?;
128:     assert_eq!(read_counter(&journal)?, Some(1));
129:     drop(journal);
130:     let journal2 = FjallJournal::open(dir.path(), None)?;
131:     fixture.check(&journal2, &artifact, RuntimePolicy::Strict)?;
132:     assert_eq!(read_counter(&journal2)?, Some(1));
133:     let artifact2 = fixture.submit(&journal2, RuntimePolicy::Strict)?;
134:     assert_eq!(artifact2.accepted_at_seq.get(), 2);
135:     fixture.check(&journal2, &artifact2, RuntimePolicy::Strict)?;
136:     fixture.check(&journal2, &artifact, RuntimePolicy::Strict)?;
137:     assert_ne!(artifact2.digest, artifact.digest);
138:     assert_eq!(read_counter(&journal2)?, Some(2));
139:     Ok(())
140: }
