40:         digest: zero_workflow_digest(),
41:         source_digest: workflow.digest(),
42:         policy_digest: compute_policy_digest(workflow)?,
43:         ir,
44:         verification: proof,
45:         accepted_at_seq: EventSeq::new(0),
46:         required_capabilities: required_capabilities_from_contracts(contracts)?,
47:         action_contracts: contracts.to_vec().into_boxed_slice(),
48:     };
